#!/usr/bin/env python3
"""Generate docs/pumpfun/03-sixteen-days-tick-level.md: the full research report on pump.fun, Oct 5-20, 2026, computed from the
files in this repository (16 daily collector outputs, the level-B crowd and buyer files, the robustness and food-chain
results, and the DefiLlama responses). Nothing in the report is typed by hand except the section introductions.
Run from the repository root:  python3 scripts/report_pumpfun.py"""
import json, csv, gzip, glob, os, statistics, collections, datetime as dt, math
S = 'data/pumpfun-16d'; R = 'data/raw'; OUT = 'docs/pumpfun/03-sixteen-days-tick-level.md'; FAM = 'pf|SOL'
days = sorted(os.path.basename(f)[:10] for f in glob.glob(os.path.join(S, '2026-10-*.json')))
J = {}
for d in days:
    with open(os.path.join(S, d + '.json')) as fh: J[d] = json.load(fh)
T = {d: J[d]['familles'][FAM]['tout'] for d in days}
L = []
def h(x): L.append(x); L.append('')
def table(header, rows):
    L.append('| ' + ' | '.join(header) + ' |'); L.append('|' + '---|' * len(header))
    for r in rows: L.append('| ' + ' | '.join(str(c) for c in r) + ' |')
    L.append('')
def pct(x, n=1): return '—' if x is None else f'{100*x:+.{n}f} %'
def part(x, n=1): return '—' if x is None else f'{100*x:.{n}f} %'
def num(x): return '—' if x is None else f'{x:,.0f}'
def mean(a): a = [x for x in a if x is not None]; return statistics.mean(a) if a else None
def med(a): a = [x for x in a if x is not None]; return statistics.median(a) if a else None
short = lambda d: d[5:]

h('# pump.fun under the instrument: sixteen days, every number\n')
h(f'*Generated by `scripts/report_pumpfun.py` on {dt.date.today().isoformat()} from the files in this repository. Window: {J[days[0]]["fenetre"][0]} → {J[days[-1]]["fenetre"][1]} UTC, {len(days)} UTC days, one run of the lab tool per day on the collector\'s hourly files (`scripts/lab/solana-courbes.mjs`, unchanged across the window). Family measured: pump.fun tokens quoted in SOL (`pf|SOL`); the "mayhem" variant, other quote tokens and Raydium LaunchLab are read for control and reported separately. All P&L figures are on bonding-curve flows, curve fees included; "strict" counts unsold tokens at zero, "valued" prices them at the last curve price. Every table can be regenerated with `make report`.*')

# ---------------- 1. Coverage and verification ----------------
h('## 1. Coverage, integrity and verification of the curve formula\n')
h('Each day the tool reads the hourly files of the collector (24 files plus the first hour of the next day to close positions), checks that no minute is missing, and verifies every swap against the bonding-curve formula (a buy must move the price up, a sell down; the reconstructed price must match the on-chain state). The canary compares the number of pump.fun program transactions received with the number expected from the chain.')
rows = []
for d in days:
    c = J[d]['couverture']; le = J[d]['lecture']; v = J[d]['verifications']; cp = c['canari']['pumpfun']; cl = c['canari']['launchlab']
    rows.append([short(d), f"{c['minutesLues']}/{c['minutesAttendues']}", c['minutesSansSource'], f"{le['transactions']:,}", f"{le['comptes']:,}", f"{le['bundles']:,}", f"{cp['recues']/cp['attendues']:.3f}", f"{cl['recues']/cl['attendues']:.3f}" if cl['attendues'] else '—', f"{v['echanges']:,}", part(v['formuleOk']/v['echanges'], 2), f"{v['ecartRelMax']:.3f}", f"{v['sensAchatBaisse']+v['sensVenteHausse']:,}", f"{J[d]['dureeSlot']*1000:.0f} ms"])
table(['day', 'minutes read', 'no source', 'transactions', 'accounts', 'bundles', 'canary pump.fun', 'canary LaunchLab', 'swaps verified', 'formula OK', 'max rel. dev.', 'wrong-direction swaps', 'slot'], rows)
tot_tx = sum(J[d]['lecture']['transactions'] for d in days); tot_sw = sum(J[d]['verifications']['echanges'] for d in days); tot_ok = sum(J[d]['verifications']['formuleOk'] for d in days)
h(f'Totals: {tot_tx:,} transactions read (about one hour in 25 is read twice to close positions, so ≈ {tot_tx*24/25:,.0f} distinct); {tot_sw:,} pump.fun/SOL swaps verified, {100*tot_ok/tot_sw:.2f} % matching the formula; {sum(J[d]["couverture"]["minutesSansSource"] for d in days)} minutes without a source out of {sum(J[d]["couverture"]["minutesAttendues"] for d in days):,}. Fees observed on the curve: {J[days[0]]["fraisBps"][0][0]} bps per swap plus {J[days[0]]["fraisCreateurBps"][0][0]} bps creator fee (checked on {J[days[0]]["fraisBps"][0][1]:,} swaps on day 1); the round trip therefore costs about 2.5 %, which is the dashed line in Fig. 3 and Fig. 4 of the paper.')

# ---------------- 2. Launches ----------------
h('## 2. Launches, graduations and the second buyer\n')
h('A token "graduates" when its curve fills and it moves to PumpSwap. "No trade" = tokens that never saw a swap. "Second buyer" = share of tokens with at least one buy within 60 s from an address outside the creator\'s cluster (strict: the buyer is not a known bundle or sniper pattern; ≥ 0.01 / 0.05 SOL: with a minimum size). `echangesMed` = median number of swaps per token.')
rows = []
for d in days:
    t = T[d]; rows.append([short(d), f"{t['jetons']:,}", f"{t['parHeure']:,.0f}", f"{t['gradues']:,}", part(t['gradues']/t['jetons'], 2), part(t['sansEchange']), part(t['secondAcheteur']), part(t['secondAcheteurStrict']), part(t['secondStrict001']), part(t['secondStrict005']), t['echangesMed'], part(t['venteTiers'])])
table(['day', 'tokens', 'per hour', 'graduated', 'grad. %', 'no trade', '2nd buyer ≤ 60 s', 'strict', '≥ 0.01 SOL', '≥ 0.05 SOL', 'median swaps/token', 'tokens with a third-party sale'], rows)
tj = sum(T[d]['jetons'] for d in days); tg = sum(T[d]['gradues'] for d in days)
h(f'Totals: {tj:,} tokens ({tj/(24*len(days)):,.0f} an hour), {tg:,} graduated ({100*tg/tj:.2f} %), {100*sum(T[d]["sansEchange"]*T[d]["jetons"] for d in days)/tj:.1f} % never traded. Tuesday Oct 6 → Tuesday Oct 20: tokens {T["2026-10-06"]["jetons"]:,} → {T["2026-10-20"]["jetons"]:,} ({100*(T["2026-10-20"]["jetons"]/T["2026-10-06"]["jetons"]-1):+.0f} %), graduations {T["2026-10-06"]["gradues"]} → {T["2026-10-20"]["gradues"]} ({100*(T["2026-10-20"]["gradues"]/T["2026-10-06"]["gradues"]-1):+.0f} %).')
h('**The other families read by the same tool** (same days; "mayhem" = pump.fun\'s variant launch mode; LaunchLab = Raydium\'s launchpad, the same-chain control):')
rows = []
for fam, lab in [('pf|SOL|mayhem', 'pump.fun mayhem'), ('pf|autres cotations', 'pump.fun, other quote tokens'), ('ll|cotation inconnue', 'Raydium LaunchLab')]:
    tj2 = sum(J[d]['familles'][fam].get('tout', J[d]['familles'][fam]).get('jetons') or 0 for d in days)
    g2 = [J[d]['familles'][fam].get('tout', J[d]['familles'][fam]).get('gradues') for d in days]; s2 = [J[d]['familles'][fam].get('tout', J[d]['familles'][fam]).get('secondAcheteur') for d in days]
    rows.append([lab, f'{tj2:,}', f'{tj2/(24*len(days)):,.0f}', f'{sum(x for x in g2 if x):,}' if any(g2) else '—', part(mean(s2)) if any(s2) else '—'])
table(['family', 'tokens, 16 days', 'per hour', 'graduated', 'mean second-buyer share'], rows)
ll = {d: J[d]['verificationsLaunchLab']['echanges'] for d in days}
w1 = mean([ll[d] for d in days if '2026-10-06' <= d <= '2026-10-12']); w2 = mean([ll[d] for d in days if '2026-10-13' <= d <= '2026-10-19'])
_alltok=sum((J[d]['familles'][f].get('tout', J[d]['familles'][f]).get('jetons') or 0) for d in days for f in ['pf|SOL','pf|SOL|mayhem','pf|autres cotations']); _allgr=sum((J[d]['familles'][f].get('tout', J[d]['familles'][f]).get('gradues') or 0) for d in days for f in ['pf|SOL','pf|SOL|mayhem','pf|autres cotations'])
h(f'**Perimeter.** All pump.fun launch modes together: {_alltok:,} tokens over the 16 days ({_alltok/(24*len(days)):,.0f} an hour), {100*_allgr/_alltok:.2f} % graduated; the SOL-quoted family measured in the paper is {100*tj/_alltok:.1f} % of tokens and {100*sum(J[d]["verificationsParFamille"]["pf|SOL"]["paires"] for d in days)/sum(J[d]["verificationsParFamille"][f]["paires"] for d in days for f in ["pf|SOL","pf|SOL|mayhem","pf|autres cotations"]):.1f} % of curve swaps.')
h(f'LaunchLab swaps per day: {w1:,.0f} (Oct 6–12) → {w2:,.0f} (Oct 13–19), {100*(w2/w1-1):+.1f} %. Day by day: ' + ', '.join(f'{short(d)} {ll[d]:,}' for d in days) + '.')

# ---------------- 3. The crowd by entry age ----------------
h('## 3. The crowd by entry age\n')
h('Positions of third-party buyers (creator excluded), grouped by the age of the token at entry. Pooled over the 16 days: positions and SOL are summed; the strict and valued P&L are weighted by the SOL paid; the median is the mean of the 16 daily medians (with its range). "Never sold" = positions with no sale at all by the end of the day\'s follow-up (00:00 UTC the next day).')
for key, lab in [('fouleNonGradues', 'Non-graduated tokens (the paper\'s universe)'), ('fouleGradues', 'Graduated tokens'), ('foule', 'All tokens')]:
    h(f'**{lab}**')
    rows = []
    ages = [x['age'] for x in T[days[0]][key]]
    for i, age in enumerate(ages):
        b = [T[d][key][i] for d in days]; P = sum(x['positions'] for x in b); SOL = sum(x['payeSol'] for x in b)
        ws = sum(x['strict'] * x['payeSol'] for x in b) / SOL if SOL else None; wv = sum(x['valorise'] * x['payeSol'] for x in b) / SOL if SOL else None
        dm = [x['medianeStrict'] for x in b]; wn = sum(x['gagnants'] * x['positions'] for x in b) / P; jv = sum(x['jamaisVendu'] * x['positions'] for x in b) / P
        rows.append([age, f'{P:,}', f'{SOL:,.0f}', pct(ws), pct(wv), pct(mean(dm)), f'{pct(min(dm))} .. {pct(max(dm))}', f'{sum(1 for m in dm if m < 0)}/{len(dm)}', part(wn), part(jv)])
    table(['entry age', 'positions', 'SOL paid', 'strict, stake-weighted', 'valued, stake-weighted', 'mean of daily medians', 'range of daily medians', 'days negative', 'winners', 'never sold'], rows)

# ---------------- 4. The 20-60 s crowd day by day ----------------
h('## 4. The 20–60 s crowd, day by day, and the robustness of the median\n')
h('From `crowd_20-60s.csv.gz` (one row per position, no address) and `results/robustness_2060.csv`. Variants: strict (unsold = 0), valued at the last curve price, excluding positions never sold, closed positions only.')
with open('results/robustness_2060.csv') as fh: _rows = list(csv.DictReader(fh))
rb = {r['day']: r for r in _rows if r['day'] and r['day'][:4] == '2026'}
rows = []
for d in days:
    t = next(x for x in T[d]['fouleNonGradues'] if x['age'] == '20-60 s'); r = rb.get(d, {})
    rows.append([short(d), f"{t['positions']:,}", f"{t['payeSol']:,.0f}", pct(t['medianeStrict']), pct(float(r['med_valued'])) if r else '—', pct(float(r['med_strict_excl_never_sold'])) if r else '—', pct(float(r['med_strict_closed_only'])) if r else '—', pct(t['strict']), part(t['gagnants']), part(t['jamaisVendu']), part(float(r['closed_share'])) if r else '—'])
table(['day', 'positions', 'SOL paid', 'median strict', 'median valued', 'median excl. never-sold', 'median closed only', 'stake-weighted strict', 'winners', 'never sold', 'closed'], rows)
try:
    agg = next(r for r in _rows if r['day'] == 'ALL')
    h(f"Pooled over 16 days ({int(agg['n']):,} positions): strict median {pct(float(agg['med_strict']))}, valued {pct(float(agg['med_valued']))}, excluding never-sold {pct(float(agg['med_strict_excl_never_sold']))}, closed only {pct(float(agg['med_strict_closed_only']))}; never-sold share {part(float(agg['never_sold_share']))}. Every variant is negative on each of the 16 days. The daily never-sold share tracks the strict median (r = −0.89) but not the median of the remaining positions (r = −0.50); the follow-up horizon is identical every day, so the higher never-sold share of Oct 19–20 is tokens that stopped trading, not censoring.")
except StopIteration: pass

# ---------------- 5. Hour by hour ----------------
h('## 5. Hour by hour: 384 hours\n')
h('For each hour of birth, the tool replays two recipes on the tokens born in that hour: buy 60 s after birth and sell 60 s later (`r6060`), and buy at 20 s, sell at 180 s (`r20180`), at the marginal price. "Robust" = trimmed mean. Below, the 24 hours of the UTC day averaged over the 16 days, then the distribution of the 384 hourly medians.')
hr = collections.defaultdict(lambda: collections.defaultdict(list))
all6 = []; all2 = []
for d in days:
    for x in J[d]['parHeure']:
        hr[x['heure']]['jetons'].append(x['jetons']); hr[x['heure']]['second'].append(x['second']); hr[x['heure']]['sansEchange'].append(x['sansEchange'])
        hr[x['heure']]['m6060'].append(x['r6060']['mediane']); hr[x['heure']]['r6060'].append(x['r6060']['robuste']); hr[x['heure']]['m20180'].append(x['r20180']['mediane']); hr[x['heure']]['r20180'].append(x['r20180']['robuste'])
        all6.append(x['r6060']['mediane']); all2.append(x['r20180']['mediane'])
rows = [[hh, f"{mean(v['jetons']):,.0f}", part(mean(v['second'])), part(mean(v['sansEchange'])), pct(mean(v['m6060'])), pct(mean(v['r6060'])), pct(mean(v['m20180'])), pct(mean(v['r20180']))] for hh, v in sorted(hr.items())]
table(['hour (UTC)', 'tokens born', '2nd buyer', 'no trade', 'median, buy 60 s / sell +60 s', 'robust', 'median, buy 20 s / sell +160 s', 'robust'], rows)
h(f'Hourly medians (buy 60 s, hold 60 s): {sum(1 for m in all6 if m < 0)}/{len(all6)} negative, from {pct(min(all6))} to {pct(max(all6))}; buy 20 s, hold 160 s: {sum(1 for m in all2 if m < 0)}/{len(all2)} negative, from {pct(min(all2))} to {pct(max(all2))}.')

# ---------------- 6. Replay grid and out-of-sample ----------------
h('## 6. The replay grid (entry × holding time) and the out-of-sample test\n')
h('Exact-state replay of a small buy at E seconds after birth, sold H seconds later, on every non-graduated token of the day, at the marginal price (`rejeu`) and with the costs of a real buy of 0.005 to 0.1 SOL (`net`). The table gives the mean over the 16 days of the daily median and of the daily robust mean, plus the number of days on which the cell\'s median was negative.')
grid = collections.defaultdict(lambda: collections.defaultdict(list))
for d in days:
    for c in T[d]['rejeu']:
        k = (c['E'], c['H']); grid[k]['med'].append(c['marginal']['mediane']); grid[k]['rob'].append(c['marginal']['robuste']); grid[k]['n'].append(c['n']); grid[k]['net01'].append(c['net']['0.01']['mediane']); grid[k]['pos'].append(c['fluxPositif'])
rows = [[f'{E} s', f'{H} s', f'{sum(v["n"]):,}', pct(mean(v['med'])), pct(mean(v['rob'])), pct(mean(v['net01'])), part(mean(v['pos'])), f'{sum(1 for m in v["med"] if m < 0)}/{len(v["med"])}'] for (E, H), v in sorted(grid.items())]
table(['entry E', 'hold H', 'positions', 'median (marginal)', 'robust (marginal)', 'median, net of a 0.01 SOL buy', 'positive flow after the buy', 'days negative'], rows)
rows = []
for d in days:
    cm = J[d]['familles'][FAM]['choixMarcheAvant']; rows.append([short(d), f"E={cm['E']} s, H={cm['H']} s", pct(cm['premiere']['mediane']), pct(cm['premiere']['robuste']), pct(cm['seconde']['mediane']), pct(cm['seconde']['robuste']), f"{cm['nSeconde']:,}"])
table(['day', 'cell chosen on the first half of the day', 'first half: median', 'robust', 'second half: median', 'robust', 'positions, 2nd half'], rows)
h('Reading: the best cell is chosen on the morning and judged on the afternoon; it stays negative on every day. The best "third-party" cell per day (`tiers`, real third-party buys rather than a replay):')
rows = []
for d in days:
    best = max(T[d]['tiers'], key=lambda x: x['robuste'] if x['robuste'] is not None else -9)
    rows.append([short(d), f"E={best['E']} s, H={best['H']} s", f"{best['n']:,}", pct(best['mediane']), pct(best['robuste']), pct(best['moyenne']), part(best['gagnants']), f"{best['miseMed']:.3f} SOL"])
table(['day', 'best cell (by robust mean)', 'positions', 'median', 'robust', 'mean', 'winners', 'median stake'], rows)

# ---------------- 7. Snipers ----------------
h('## 7. Snipers: buying in the first seconds\n')
h('The same replay for an entry 2 s or 5 s after birth (the sniper\'s slot), pooled as the mean of the daily values; `net01` = net of the costs of a 0.1 SOL buy.')
sn = collections.defaultdict(lambda: collections.defaultdict(list))
for d in days:
    for c in J[d]['sniper']: k = (c['E'], c['H']); sn[k]['n'].append(c['n']); sn[k]['med'].append(c['marginalMed']); sn[k]['rob'].append(c['marginalRob']); sn[k]['net'].append(c['net01'])
table(['entry', 'hold', 'positions (16 days)', 'median (marginal)', 'robust', 'net of a 0.1 SOL buy'], [[f'{E} s', f'{H} s', f'{sum(v["n"]):,}', pct(mean(v['med'])), pct(mean(v['rob'])), pct(mean(v['net']))] for (E, H), v in sorted(sn.items())])

# ---------------- 8. Creators ----------------
h('## 8. The creators\n')
h('`mainCreateur` = the creator\'s own trading on its tokens (what it paid and received on the curve; sales after graduation on PumpSwap are invisible, so this is a lower bound of what creators make). `venteCreateur` = how often the creator sells within 3 s of a small outside buy, against a matched control (same tokens, same age, no outside buy); the second definition also counts sales from the creation slot.')
rows = []; cp = cr = 0
for d in days:
    m = T[d]['mainCreateur']; v = T[d]['venteCreateur']; a = v['créateur']; b = v['créateur + slot de création']; cp += m['payeSol']; cr += m['recuSol']
    rows.append([short(d), f"{m['jetons']:,}", f"{m['payeSol']:,.0f}", f"{m['recuSol']:,.0f}", pct(m['pnl']), part(a['apresAchat'], 2), part(a['temoin'], 2), f"×{a['apresAchat']/a['temoin']:.1f}", part(b['apresAchat'], 2), part(b['temoin'], 2), f"×{b['apresAchat']/b['temoin']:.1f}", f"{a['nAchats']:,}"])
table(['day', 'tokens with creator trades', 'SOL paid', 'SOL received', 'creator P&L', 'sell ≤ 3 s after a buy', 'control', 'ratio', 'with creation slot', 'control', 'ratio', 'outside buys tested'], rows)
h(f'Pooled: creators paid {cp:,.0f} SOL and received {cr:,.0f} SOL on the curve ({100*(cr/cp-1):+.1f} %), i.e. ≈ {cp-cr:,.0f} SOL net paid in, before any post-graduation sale.')

# ---------------- 9. Positive control ----------------
h('## 9. Positive control: graduated tokens\n')
rows = [[short(d), T[d]['temoinPositif']['gradues'], f"×{T[d]['temoinPositif']['multiplePrixMed']:.2f}", f"{T[d]['temoinPositif']['vqFinMedSol']:.1f}"] for d in days]
table(['day', 'graduated', 'median price multiple, birth → end of curve', 'median SOL in the curve at graduation'], rows)
h('Theory: a curve that fills multiplies its price by (115/30)² ≈ 14.7; the instrument finds ×14.70 every day, which is the check that the price reconstruction is exact.')

# product breakdown by day (used below)
bd = _load('llama_pump_fees.json')['totalDataChartBreakdown'] if False else None
# ---------------- 10. Users ----------------
h('## 10. Users: active buyers, new entrants, retention, revenue per buyer\n')
act = collections.Counter(); first = {}
with gzip.open(os.path.join(S, 'active_buyers_by_day_ids.csv.gz'), 'rt') as f:
    for r in csv.DictReader(f):
        act[r['day']] += 1; first.setdefault(r['buyer_id'], r['day'])
newc = collections.Counter(first.values())
def _load(name):
    with open(os.path.join(R, name)) as fh: return json.load(fh)
rev = {dt.datetime.fromtimestamp(t, dt.timezone.utc).date().isoformat(): v for t, v in _load('llama_pump_revenue.json')['totalDataChart']}
fee = {dt.datetime.fromtimestamp(t, dt.timezone.utc).date().isoformat(): v for t, v in _load('llama_pump_fees.json')['totalDataChart']}
pr = collections.defaultdict(lambda: collections.defaultdict(float))
for _t, _dd in _load('llama_pump_fees.json')['totalDataChartBreakdown']:
    _day = dt.datetime.fromtimestamp(_t, dt.timezone.utc).date().isoformat()
    if _day in J:
        for _chain, _prods in _dd.items():
            for _p, _v in _prods.items(): pr[_day][_p] += _v
with open(os.path.join(S, 'aggregate-pumpfun.json')) as fh: A = json.load(fh); n7 = A['adresses'].get('nouvelles7jParJour', {}); ret = {r['jour']: r for r in A['adresses'].get('retentionCohortes', [])}
rows = []
for d in days:
    rt = ret.get(d, {}); rows.append([short(d), f'{act[d]:,}', f'{newc[d]:,}', f'{n7[d]:,}' if d in n7 and n7[d] is not None else '—', part(rt.get('r1')) if rt.get('r1') is not None else '—', part(rt.get('r7')) if rt.get('r7') is not None else '—', f"${rev.get(d, 0):,.0f}", f"${rev.get(d, 0)/act[d]:.2f}", f"${fee.get(d, 0)/act[d]:.2f}"])
table(['day', 'active buyers', 'first seen in the window', 'not seen in the previous 7 days', 'seen again next day', 'seen again within 7 days', 'pump.fun revenue (DefiLlama)', 'revenue per active buyer', 'fees per active buyer'], rows)
w1 = mean([act[d] for d in days if '2026-10-06' <= d <= '2026-10-12']); w2 = mean([act[d] for d in days if '2026-10-13' <= d <= '2026-10-19'])
h(f'Active buyers per day: {w1:,.0f} (Oct 6–12) → {w2:,.0f} (Oct 13–19), {100*(w2/w1-1):+.1f} %; {len(first):,} distinct addresses over the window. "First seen in the window" is mechanically high on the first days (everyone is new on day 1); the 7-day definition is the honest one and starts on day 8. Retention: most new entrants do not come back (the Oct 5 cohort is inflated by regulars who were simply absent on day 1).')


# ---- same-weekday comparisons (every pair Oct 13-19 vs Oct 6-12) ----
h('**Same weekday, one week apart (Oct 13–19 against Oct 6–12), every pair:**')
_rows=[]; _down=collections.Counter()
for d in [f'2026-10-{x}' for x in range(13,20)]:
    p_=(dt.date.fromisoformat(d)-dt.timedelta(days=7)).isoformat(); dd=dt.date.fromisoformat(d); pp=dt.date.fromisoformat(p_)
    tokd=T[d]['jetons']/T[p_]['jetons']-1; grd=T[d]['gradues']/T[p_]['gradues']-1; bd=act[d]/act[p_]-1; rd=rev.get(d,0)/rev.get(p_,1)-1
    cf=pr[d].get('pump.fun',0)/pr[p_].get('pump.fun',1)-1 if pr.get(p_) else None; ps=pr[d].get('PumpSwap',0)/pr[p_].get('PumpSwap',1)-1 if pr.get(p_) else None
    for k,v in [('buyers',bd),('tokens',tokd),('graduations',grd),('revenue',rd),('curve fees',cf),('PumpSwap fees',ps)]:
        if v is not None and v<0: _down[k]+=1
    _rows.append([f"{dd.strftime('%a')} {short(d)} vs {short(p_)}", pct(bd,0), pct(tokd,0), pct(grd,0), pct(rd,0), pct(cf,0) if cf is not None else '—', pct(ps,0) if ps is not None else '—'])
table(['pair', 'active buyers', 'tokens created', 'graduations', 'revenue (DefiLlama)', 'curve fees', 'PumpSwap fees'], _rows)
h('Pairs down out of seven: ' + ', '.join(f'{k} {v}/7' for k,v in _down.items()) + f". Log-linear slope of active buyers over the 16 days: {100*(math.exp(7*(lambda xs,ys: (sum((x-statistics.mean(xs))*(y-statistics.mean(ys)) for x,y in zip(xs,ys))/sum((x-statistics.mean(xs))**2 for x in xs)))(list(range(len(days))), [math.log(act[d]) for d in days]))-1):+.1f} % a week.")

# ---------------- 11. Food chain ----------------
h('## 11. The food chain: who loses, by how many positions they take\n')
try:
    with open('results/food_chain_recomputed.json') as fh: fc = json.load(fh)
    for v, lab in [('nongrad', 'Non-graduated tokens (Fig. 4 of the paper)'), ('all', 'All tokens')]:
        h(f'**{lab}** — {fc[v]["hands"]:,} addresses, {fc[v]["positions"]:,} positions, {fc[v]["sol"]:,.0f} SOL.')
        table(['positions in 16 days', 'addresses', '% of addresses', '% of positions', '% of SOL', 'median strict P&L'], [[s['label'], f"{s['hands']:,}", f"{s['pctHands']:.2f} %", f"{s.get('pctPositionsOfVariant', s['pctPositions']):.1f} %", f"{s.get('pctSolOfVariant', s['pctSol']):.1f} %", f"{s['median']:+.1f} %"] for s in fc[v]['segments']])
    sp = fc['script_profile']; h(f"Script profile ({sp['definition']}): {sp['hands']:,} addresses, {sp['pctHands']:.2f} % of all addresses.")
except FileNotFoundError: h('`results/food_chain_recomputed.json` missing: run `make foodchain` (needs the per-position files).')

# ---------------- 12. Public series ----------------
h('## 12. The same days in the public series (DefiLlama)\n')
prods = sorted({p for d in pr for p in pr[d]})
table(['day'] + [f'{p} fees ($)' for p in prods] + ['revenue ($)', 'take rate'], [[short(d)] + [f'{pr[d].get(p, 0):,.0f}' for p in prods] + [f"{rev.get(d, 0):,.0f}", part(rev.get(d, 0)/fee.get(d, 1))] for d in days])
w = lambda p, a, b: sum(pr[d].get(p, 0) for d in days if a <= d <= b)
h('Week on week (Oct 6–12 → Oct 13–19): ' + '; '.join(f"{p} {100*(w(p,'2026-10-13','2026-10-19')/w(p,'2026-10-06','2026-10-12')-1):+.0f} %" for p in prods if w(p, '2026-10-06', '2026-10-12')) + f"; revenue {100*(sum(rev.get(d,0) for d in days if '2026-10-13'<=d<='2026-10-19')/sum(rev.get(d,0) for d in days if '2026-10-06'<=d<='2026-10-12')-1):+.0f} %.")

# ---------------- 13. Limits ----------------
h('## 13. What the instrument does not see\n')
h('- Sales after graduation on PumpSwap are invisible to the curve reader: P&L on graduated tokens and creators\' P&L are lower bounds.\n- The strict rule counts unsold tokens at zero; the valued variant and the never-sold exclusion are in section 4.\n- Bots, snipers and wash trades are not filtered out of "the crowd"; if anything they make its median less negative.\n- Solana transaction, priority and trading-bot fees are not deducted: the crowd\'s true P&L is worse than shown.\n- An address is not a person; co-signing addresses are not merged (merging was tested on the food-chain run and changed nothing).\n- Sixteen days are one market regime (post-peak October 2026); consecutive days are not independent, so the day-level sign tests are indicative.\n- The graduation rate measured here (2.5 %) is above the 0.6–1.0 % reported in the literature for 2024–2025: a mania month, and a different perimeter (tokens quoted in SOL only).')
os.makedirs(os.path.dirname(OUT), exist_ok=True)
with open(OUT, 'w') as fh: fh.write('\n'.join(L)); print('ok', OUT, len(' '.join(L).split()), 'words')
